let fixture name = List.find (fun value -> Json.string (get "name" value) = name) fixtures
let authority value =
  Realization_request.of_json (get "request" value), A.of_json (get "candidate" value),
  List.map Execution_data.Input_frame.of_json (Json.array (get "history" value)), Runtime_number.of_json (get "until" value)
let run ?limits ?parent value =
  let request,candidate,history,until = authority value in
  C.check_with_usage ~until ?limits ?parent request candidate history
let compare name expected result =
  check (Canonical.encode (E.to_json result) = Canonical.encode expected) (name ^ ": complete independently expected report changed")
let () =
  check (List.length fixtures = 62) "Independent source-provenance fixture census changed";
  List.iter (fun value ->
    let name = Json.string (get "name" value) in
    let result,usage = run value in
    compare name (get "expected" value) result;
    check (E.fingerprint result = Json.string (get "fingerprint" value)) (name ^ ": full report identity changed");
    check (usage.work_charged > 0) (name ^ ": fresh source and runtime work was not charged")) fixtures;
  let base = fixture "base" in
  let result,usage = run base in
  let parent = W.create ~profile:"literal.synthetic.provenance" ~error_code:"literal_provenance_parent" ~maximum:50_000_000 () in
  let nested,nested_usage = run ~parent base in
  compare "shared_parent" (E.to_json result) nested;
  check (usage.work_charged = nested_usage.work_charged && W.remaining parent = 50_000_000 - nested_usage.work_charged)
    "Nested source provenance did not charge its one shared parent";
  let tiny = W.create ~profile:"literal.synthetic.provenance" ~error_code:"literal_provenance_parent" ~maximum:1 () in
  reject "literal_provenance_parent" (fun () -> run ~parent:tiny base);
  List.iter (fun (code,limits) -> reject code (fun () -> run ~limits base))
    ["realization_work_limit",C.make_limits ~max_work:1 ();
     "realization_input_limit",C.make_limits ~max_request_bytes:1 ();
     "realization_report_limit",C.make_limits ~max_report_bytes:1 ();
     "realization_report_limit",C.make_limits ~max_report_nodes:1 ();
     "realization_monitor_limit",C.make_limits ~max_monitor_items:1 ()];
  (* An early policy rejection exercises an exact work boundary without engine
     failure-publication capacity: every phase through complete report export
     consumes the same immutable authority and the same counted operations. *)
  let early = fixture "both_ordered_violations" in
  let early_result,early_usage = run early in
  let exact,_ = run ~limits:(C.make_limits ~max_work:early_usage.work_charged ()) early in
  compare "exact_early_work" (E.to_json early_result) exact;
  reject "realization_work_limit" (fun () -> run ~limits:(C.make_limits ~max_work:(early_usage.work_charged-1) ()) early);
  let exact_parent = W.create ~profile:"literal.synthetic.exact" ~error_code:"literal_exact_parent"
    ~maximum:early_usage.work_charged () in
  let exact,_ = run ~parent:exact_parent early in
  compare "exact_early_parent" (E.to_json early_result) exact;
  check (W.remaining exact_parent = 0) "Exact parent allowance did not include complete early publication";
  let short_parent = W.create ~profile:"literal.synthetic.short" ~error_code:"literal_short_parent"
    ~maximum:(early_usage.work_charged-1) () in
  reject "literal_short_parent" (fun () -> run ~parent:short_parent early);
  (* A second failed phase cannot silently acquire a new allowance, while a new
     independent invocation remains unpoisoned by the failed budget. *)
  reject "literal_short_parent" (fun () -> run ~parent:short_parent early);
  let fresh,_ = run base in
  compare "failure_then_fresh_invocation" (E.to_json result) fresh;
  (* Cumulative derived metadata is governed by the common retained-item limit.
     A successful public result proves actual lineage comparison and execution;
     a tiny inventory cannot become UNKNOWN or a partial accepted report. *)
  List.iter (fun name -> reject "realization_monitor_limit" (fun () ->
    run ~limits:(C.make_limits ~max_monitor_items:32 ()) (fixture name)))
    ["shared_alias_unused_memory_native";"shared_alias_unused_memory_de_morgan"];
  Printf.printf "synthetic provenance: %d checks across 62 complete original reports, both strategies/profiles, alias/memory updates, actual execution and shared resource boundaries\n" !checks
